if (std::abs(len) < 1e-8) {
    *v2 = Vector3<T>(1, 0, 0);
    *v3 = Vector3<T>(0, 1, 0);
} else {
    *v1 = Vector3<T>(v1.x / len, v1.y / len, v1.z / len);
    if (std::abs(v1.x) > std::abs(v1.y) && std::abs(v1.x) > std::abs(v1.z)) {
        *v2 = Vector3<T>(0, -v1.z, v1.y);
    } else if (std::abs(v1.y) > std::abs(v1.z)) {
        *v2 = Vector3<T>(v1.z, 0, -v1.x);
    } else {
        *v2 = Vector3<T>(-v1.y, v1.x, 0);
    }
    *v3 = std::cross(*v1, *v2);
}
